fields.formula:
IF(
    LEFT(Phone, 2) = "+1",
    /* If it starts with "+1", remove "+" and parentheses */
    "1" & SUBSTITUTE(SUBSTITUTE(RIGHT(Phone, LEN(Phone) - 2), "(", ""), ")", ""),
    IF(
        LEFT(Phone, 1) = "1",
        /* If it already starts with "1", just clean up parentheses */
        SUBSTITUTE(SUBSTITUTE(Phone, "(", ""), ")", ""),
        /* If it doesn't start with "1" or "+1", prepend "1" and clean up parentheses */
        "1" & SUBSTITUTE(SUBSTITUTE(Phone, "(", ""), ")", "")
    )
)
